<template>
  <div class="container py-5">
    <!-- AdminNav Component -->
    <AdminNav />

    <table class="table">
      <thead class="thead-dark">
        <tr>
          <th scope="col">
            #
          </th>
          <th scope="col">
            Email
          </th>
          <th scope="col">
            Role
          </th>
          <th scope="col" width="140">
            Action
          </th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="user in users" :key="user.id">
          <th scope="row">
            {{ user.id }}
          </th>
          <td>{{ user.email }}</td>
          <td>{{ user.isAdmin !== true ? 'user' : 'admin' }}</td>
          <td>
              <button :disabled="togglingId === user.id" v-if="user.id !== currentUser.id" @click.stop.prevent="toggleUserRole(user)" type="button"
              class="btn btn-link">
              {{ togglingId === user.id ? '處理中...' : (user.isAdmin === true) ? 'set as user' : 'set as admin' }}
            </button>
          </td>
        </tr>
      </tbody>
    </table>
  </div>
</template>

<script>
import AdminNav from '@/components/AdminNav.vue';
import adminAPI from '@/apis/admin'
import { Toast } from '@/utils/helpers';
import { mapState } from 'vuex';

export default {
  name: 'AdminUsers',
  components: {
    AdminNav,
  },
  data() {
    return {
      users: [],
      togglingId: null
    }
  },
  computed: {
    ...mapState(['currentUser'])
  },
  created() {
    this.fetchUsers()
  },
  methods: {
    async fetchUsers() {
      try {
        const { data } = await adminAPI.users.get()
        this.users = data.users
      } catch (error) {
        console.log('error', error)

        Toast.fire({
          icon: 'error',
          title: '無法取得所有使用者資料，請稍候再試'
        })
      }
    },
    async toggleUserRole(user) {
      try {
        this.togglingId = user.id
        const { id: userId, isAdmin } = user
        const toggledIsAdmin = !isAdmin
        const { data } = await adminAPI.users.toggleUserRole({ userId, isAdmin: toggledIsAdmin })
        if (data.status !== 'success') {
          throw new Error(data.message)
        }

        this.users = this.users.map(user => {
        if (user.id === userId) {
          return {
            ...user,
            isAdmin: !user.isAdmin
          }
        }
        return user
      })
      this.togglingId = null
    } catch (error) {
        this.togglingId = null
        console.log('error', error)

        Toast.fire({
          icon: 'error',
          title: '無法改變使用者權限，請稍候再試'
        })
      }
    }
  }
}
</script>